using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query; using Xunit;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Query;
public sealed class AstronomyKnowledgeStatementOrderTests{[Fact]public void Valid_order_keeps_values(){var o=new AstronomyKnowledgeStatementOrder(AstronomyKnowledgeStatementSortField.Revision,AstronomyKnowledgeQuerySortDirection.Descending,2);Assert.Equal(AstronomyKnowledgeStatementSortField.Revision,o.Field);Assert.Equal(AstronomyKnowledgeQuerySortDirection.Descending,o.Direction);Assert.Equal(2,o.Priority);}[Fact]public void Invalid_values_rejected(){Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeStatementOrder((AstronomyKnowledgeStatementSortField)99,AstronomyKnowledgeQuerySortDirection.Ascending));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeStatementOrder(AstronomyKnowledgeStatementSortField.Id,(AstronomyKnowledgeQuerySortDirection)99));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeStatementOrder(AstronomyKnowledgeStatementSortField.Id,AstronomyKnowledgeQuerySortDirection.Ascending,-1));}[Fact]public void Validator_detects_duplicate_field_and_priority(){var q=new AstronomyKnowledgeStatementQuery(ordering:[new(AstronomyKnowledgeStatementSortField.Id,AstronomyKnowledgeQuerySortDirection.Ascending,0),new(AstronomyKnowledgeStatementSortField.Id,AstronomyKnowledgeQuerySortDirection.Descending,0)]);var issue=KnowledgeQueryFixture.Validator().Validate(q).Issues;Assert.Equal(AstronomyKnowledgeQueryValidationCode.DuplicateOrderField,issue[0].Code);Assert.Equal(AstronomyKnowledgeQueryValidationCode.DuplicateOrderPriority,issue[1].Code);}}
